        raise AttributeError("No record information available")

    items = self._record

    if not keys:
        return {key: items[key] for key in items}

    result = {}
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(items):
                raise IndexError("Index out of bounds")
            result[items.keys()[key]] = items.values()[key]
        elif isinstance(key, str):
            if key not in items:
                result[key] = None
            else:
