def round_half_to_even(n):
    """Round a number to the nearest integer, rounding half to even if the number is exactly halfway between two integers.

    Args:
        n (float): The number to round

    Returns:
        int: The rounded integer
    """
    if n >= 0:
        return int(n + 0.5 - 0.5 * (n + 0.5) % 1)
    else:
        return int(n - 0.5 + 0.5 * (n - 0.5) % 1)

