import math

def round_half_to_even(n):
    """ Rounds numbers to the nearest integer, with ties going to the nearest even number """
    if not isinstance(n, (int, float)):
        raise ValueError("Input must be a number")

    fractional, integer = math.modf(n)
    if fractional == 0.5:
        return integer + 1 if integer % 2 != 0 else integer
    elif fractional == -0.5:
        return integer - 1 if integer % 2 != 0 else integer
    else:
        return round(n)
