import inspect

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    class PointSubclass(AbstractGeometryElement):
        __name__ = name
        __slots__ = fields + ['srid']

        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)
            self.srid = srid_map.get(self.type, None)

        def to_folia(self):
            elem = Element(self.xmltag)
            for field in fields:
                if field in kwargs:
                    elem.add_content(kwargs[field])
            if self.srid:
                elem['srid'] = str(self.srid)
            return elem

        def to_xml(self):
            return self.to_folia().tostring()

        @classmethod
        def from_folia(cls, elem):
            if elem.tag != cls.xmltag:
                raise ValueError(f"Expected XML element '{cls.xmltag}', but found '{elem.tag}'")
            kwargs = {field: elem.get(field, None) for field in fields}
            srid = elem.get('srid')
            if srid:
                kwargs['srid'] = int(srid)
            return cls(**kwargs)

        @classmethod
        def from_xml(cls, xml):
            return cls.from_folia(Element(xml))

    PointSubclass.xmltag = name
    PointSubclass.type = name
    PointSubclass.fields = fields
    PointSubclass.srid_map = srid_map

    return PointSubclass
