def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        for field in fields:
            setattr(self, field, kwargs.get(field, None))

    def validate_srid(self):
        if self.srid and self.srid not in srid_map:
            raise ValueError(f"Invalid SRID: {self.srid}")

    __annotations__ = {
        'srid': int,
    }

    for field in fields:
        __annotations__[field] = type(fields[field])

    class PointMeta(type):
        def __new__(cls, name, bases, dct):
            dct['__init__'] = __init__
            dct['validate_srid'] = validate_srid
            dct['__annotations__'] = __annotations__
            return super().__new__(cls, name, bases, dct)

    Point = PointMeta(name, (object,), {})
    return Point

