    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """

    if key is None:
        key = hashkey

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Create a key for the cache based on the function arguments
            memo_key = (func, args, tuple(kwargs.items()))

            # Check if the result is already in the cache
            if memo_key in cache:
                return cache[memo_key]

            # Lock the cache if needed
            if lock:
                lock.acquire()

            try:
                # Call the function and store the result in the cache
                result = func(*args, **kwargs)
                cache[memo_key] = result
                return result
            finally:
                # Release the lock if needed
                if lock:
                    lock.release()

        return wrapper

    return decorator
