def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    class _TTLCache:
        def __init__(self, maxsize, ttl, typed):
            self.maxsize = maxsize
            self.ttl = ttl
            self.cache = {}
            self._cache_get = self.cache.get
            self._cache_set = self.cache.__setitem__
            self._cache_del = self.cache.__delitem__
            self.locks = {}
            self._locks_get = self.locks.get
            self._locks_set = self.locks.__setitem__
            self._locks_del = self.locks.__delitem__
            self.timer = timer
            self.typed = typed

        def __call__(self, func):
            @wraps(func)
            def _wrapped(*args, **kwargs):
                key = self._make_key(args, kwargs, typed=self.typed)
                lock = self._locks_get(key)
                if lock is None:
                    lock = []  # a new lock (just a sentinel list is enough)
                    self._locks_set(key, lock)
                with lock:
                    result = self._cache_get(key)
                    if result:
                        _, expire = result
                        if expire > self.timer():
                            return result[0]
                        else:
                            self._cache_del(key)
                            del self.locks[key]
                    result = func(*args, **kwargs)
                    expire = self.timer() + self.ttl
                    self._cache_set(key, (result, expire))
                    if len(self.cache) > self.maxsize:
                        oldest_key = min(self.cache, key=lambda k: self.cache[k][1])
                        del self.cache[oldest_key]
                        del self.locks[oldest_key]
                    return result
            return _wrapped

        def _make_key(self, args, kwargs, typed=False):
            if not typed:
                args = tuple(type(a) if isinstance(a, tuple) else a for a in args)
                kwargs = frozenset(kwargs.items())
            return _make_key(args, kwargs, typed)

    return _TTLCache(maxsize, ttl, typed)
