    from functools import wraps
    from collections import OrderedDict

    class MRUCache(dict):
        def __init__(self, maxsize, typed, *args, **kwargs):
            super().__init__(*args, **kwargs)
            self.__maxsize__ = maxsize
            self.__typed__ = typed
            self.__order__ = OrderedDict()

        def __getitem__(self, key):
            value = super().__getitem__(key)
            self.__order__.move_to_end(key)
            return value

        def __setitem__(self, key, value):
            if self.__typed__ and not isinstance(key, tuple):
                key = (type(key), key)
            if key not in self and len(self) >= self.__maxsize__:
                discared_key, _ = self.__order__.popitem(last=False)
                if self.__typed__:
                    discared_key = discared_key[1]
                del self[discared_key]
            self.__order__.move_to_end(key)
            super().__setitem__(key, value)

        def __delitem__(self, key):
            if self.__typed__:
                key = (type(key), key)
            super().__delitem__(key)
            del self.__order__[key]

        def clear(self):
            super().clear()
            self.__order__.clear()

    def decorator(func):
        cache = MRUCache(maxsize, typed)

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (func, args, tuple(kwargs.items()))
            if key in cache:
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            return result

        return wrapper

    return decorator

