def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def decorating_function(user_function):
        wrapper_cache = {}
        wrapper_typed = typed
        wrapper_maxsize = maxsize

        if maxsize and maxsize is not None:
            cache_get = wrapper_cache.get
            cache_set = wrapper_cache.__setitem__
            cache_del = wrapper_cache.__delitem__

            def wrapper(*args, **kwds):
                # Set typing if we haven't already and we're type sensitive
                if wrapper_typed:
                    if not isinstance(args[1:], tuple):
                        raise TypeError('A positional argument must be provided as a tuple')
                    key = args[0], args[1], kwds
                elif not kwds:
                    key = args
                else:
                    key = args, frozenset(kwds.items())

                if key in cache:
                    cache_get(key)
                    return cache[key]
                else:
                    cache_set(key, result = user_function(*args, **kwds))
                    if len(wrapper_cache) >= wrapper_maxsize:
                        wrapper_cache.popitem(last=False)
                    return result
        elif maxsize is None:
            def wrapper(*args, **kwds):
                if not wrapper_typed:
                    key = args
                elif args and isinstance(args[1:], tuple):
                    key = args[0], args[1], kwds
                elif kwds:
                    key = args, frozenset(kwds.items())
                else:
                    raise TypeError('A positional argument must be provided as a tuple')

                if key not in wrapper_cache:
                    wrapper_cache[key] = user_function(*args, **kwds)
                return wrapper_cache[key]
        else:
            raise ValueError('Expected maxsize an int or None')

        return functools.update_wrapper(wrapper, user_function)

    return decorating_function
