from collections import OrderedDict

class Node:
    def __init__(self, key, value):
        self.key = key
        self.value = value
        self.count = 1

class LFUCache:
    def __init__(self, maxsize=128, typed=False):
        self.maxsize = maxsize
        self.typed = typed
        self.cache = OrderedDict()
        self.frequency = {}
        self.min_freq = 0

    def __getitem__(self, key):
        if key not in self.cache:
            raise KeyError(key)
        node = self.cache[key]
        self.frequency[node.count].remove(key)
        if not self.frequency[node.count]:
            del self.frequency[node.count]
        node.count += 1
        self.frequency[node.count] = self.frequency.get(node.count, [])
        self.frequency[node.count].append(key)
        return node.value

    def __setitem__(self, key, value):
        if key in self.cache:
            node = self.cache[key]
            self.frequency[node.count].remove(key)
            if not self.frequency[node.count]:
                del self.frequency[node.count]
        elif len(self.cache) >= self.maxsize:
            lfu_keys = self.frequency[self.min_freq]
            lfu_key = lfu_keys.pop(0)
            if not lfu_keys:
                del self.frequency[self.min_freq]
            del self.cache[lfu_key]
            self.min_freq += 1
        self.cache[key] = Node(key, value)
        self.cache[key].count = 1
        self.frequency[1] = self.frequency.get(1, [])
        self.frequency[1].append(key)
        self.min_freq = 1

    def __contains__(self, key):
        return key in self.cache

    def __len__(self):
        return len(self.cache)

    def __iter__(self):
        for key in self.cache:
            yield key

    def __reversed__(self):
        for key in reversed(self.cache):
            yield key

    def clear(self):
        self.cache.clear()
        self.frequency.clear()
        self.min_freq = 0

