def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """

    class LFUCache:
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.cache = {}
            self.frequency = {}

        def __call__(self, func):
            def wrapper(*args, **kwargs):
                key = (args, tuple(kwargs.items())) if self.typed else (tuple(args), tuple(kwargs.items()))
                if key not in self.cache:
                    if len(self.cache) >= self.maxsize:
                        self._evict()
                    result = func(*args, **kwargs)
                    self.cache[key] = result
                    self.frequency[key] = 1
                else:
                    self.frequency[key] += 1
                return self.cache[key]

            def _evict(self):
                min_freq = min(self.frequency.values())
                keys_to_evict = [k for k, freq in self.frequency.items() if freq == min_freq]
                for key in keys_to_evict:
                    del self.cache[key]
                    del self.frequency[key]

            return wrapper

    return LFUCache(maxsize, typed)()

