def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return: The exception readable string
    :rtype: str
    """
    def format_stack(frame, max_level, current_level=0):
        if current_level >= max_level:
            return "..."

        return f"{frame.f_code.co_filename}:{frame.f_lineno} -> {frame.f_code.co_name}"

    def format_path(path, max_path_level):
        if max_path_level < 0:
            return "..."
        elif len(path) > max_path_level:
            return f"{path[-max_path_level:][::-1]} -> ... -> {path[0]}"
        else:
            return " -> ".join(path[::-1])

    import traceback
    tb = traceback.extract_tb(e.__traceback__)
    frames = [tb.reverse()[i] for i in range(len(tb))]

    path = [frame.f_code.co_filename for frame in frames]
    if max_path_level > 0:
        path = path[:max_path_level]

    formatted_frames = [format_stack(frame, max_level) for frame in frames]
    formatted_path = format_path(path, max_path_level)

    return f"{type(e).__name__}: {str(e)}\nPath: {formatted_path}\nStack Trace:\n{'\n'.join(formatted_frames)}"

