def format_traceback(cls, tb, max_path_level):
    if not tb:
        return []

    if max_path_level <= 0:
        return ["<Max path level reached>"]

    try:
        tb_next = tb.tb_next
        filename = tb.tb_frame.f_code.co_filename
        linenum = tb.tb_frame.f_lineno
        name = tb.tb_frame.f_code.co_name

        return [f"  File \"{filename}\", line {linenum}, in {name}"] + cls.format_traceback(tb_next, max_path_level - 1)
    except Exception as e1:
        return [f"Error in formatting traceback frame: {e1}"]
