def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    def is_proper_subset(a, b):
        return a != b and a.issubset(b)

    def reduce_classes(classes):
        n = len(classes)
        for i in range(n):
            for j in range(i + 1, n):
                if is_proper_subset(classes[i], classes[j]):
                    classes[j] = None
                elif is_proper_subset(classes[j], classes[i]):
                    classes[i] = None
        return [c for c in classes if c is not None]

    result = reduce_classes(classes)
    return result
