        for base in cls.__bases__:
            graph[base].append(cls)
            in_degree[cls] += 1

    # Topological sort using Kahn's algorithm
    queue = [cls for cls in in_degree if in_degree[cls] == 0]
    result = []

    while queue:
        cls = queue.pop(0)
        result.append(cls)

        for neighbor in graph[cls]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # Check for cycles
    if len(result) != len(classes):
        raise ValueError("The input classes contain cycles")

    return result

