def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    def is_subclass(a, b):
        return issubclass(a, b) and a is not b

    minimal = []
    for cls in classes:
        if not any(is_subclass(cls, c) for c in minimal):
            minimal.append(cls)

    minimal.sort(key=classes.index)
    return minimal
