def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Remove duplicates by converting the list to a set
    unique_classes = set(classes)

    # Filter out classes that are subclasses of another class in the list
    minimal_classes = []
    for cls in unique_classes:
        if not any(issubclass(c, cls) for c in unique_classes if c != cls):
            minimal_classes.append(cls)

    # Sort the minimal classes by their level in the class hierarchy
    def sort_key(cls):
        return sum(issubclass(c, cls) for c in unique_classes)

    minimal_classes.sort(key=sort_key)

    return minimal_classes

