    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    for field, value in self.fields.items():
        if field.startswith('error'):
            field_name = field[5:]
            if field_name in ['x', 'y', 'z']:
                if 'error' not in context.value:
                    context.value['error'] = {}
                if field_name not in context.value['error']:
                    context.value['error'][field_name] = {}
                context.value['error'][field_name]['index'] = value
        else:
            if 'value' not in context:
                context.value = {}
            if field not in context.value:
                context.value[field] = value

    for error_index, error_messages in self.errors.items():
        if 'error' not in context:
            context.error = []
        context.error.append(error_index)

    for subcontext in self.subcontexts:
        if 'subcontexts' not in context:
            context.subcontexts = []
        context.subcontexts.append(subcontext)

