    if level == 0:
        return {}

    if level == -1:
        return {k: v for k, v in d1.items() if k not in d2 or v != d2[k]}

    result = {}
    for k, v in d1.items():
        if k not in d2:
            result[k] = v
        else:
            v_diff = difference(v, d2[k], level - 1)
            if v_diff:
