def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """Convert the SQL query to use the out-style parameters instead of the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -   *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -   The formatted SQL query (:class:`str` or :class:`bytes`).

    -   A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """

    from collections.abc import Iterable, Mapping, Sequence

    formatted_sql = sql
    out_params = []

    if isinstance(sql, str):
        in_style = self.SQLParams.in_style == 'named'
    elif isinstance(sql, bytes):
        in_style = self.SQLParams.in_style == 'named'
    else:
        raise TypeError("sql must be a str or bytes")

    for params in many_params:
        if in_style:
            if not isinstance(params, Mapping):
                raise ValueError("params must be a Mapping if in_style is named")
        else:
            if not isinstance(params, Sequence):
                raise ValueError("params must be a Sequence if in_style is ordinal")

        formatted_sql, params_out = self.formatone(sql, params)
        formatted_sql = formatted_sql.replace('%s', '?')

        out_params.append(params_out)

    return formatted_sql, out_params

def formatone(self, sql: AnyStr, params: Union[Mapping[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], List[Any]]]:
    import re

    if isinstance(sql, str):
        in_style = self.SQLParams.in_style == 'named'
    elif isinstance(sql, bytes):
        in_style = self.SQLParams.in_style == 'named'
    else:
        raise TypeError("sql must be a str or bytes")

    if in_style:
        pattern = re.compile(r':(\w+)')
    else:
        pattern = re.compile(r'%s')

    def replace(match: re.Match) -> str:
        if in_style:
            key = match.group(1)
            return self.format_value(params[key], escape=True)
        else:
            if isinstance(params, Sequence):
                return self.format_value(params[0], escape=True)
            else:
                raise ValueError("params must be a Sequence if in_style is ordinal")

    formatted_sql = pattern.sub(replace, sql)
    return formatted_sql, params

    def format_value(self, value: Any, escape: bool = True) -> Any:
        if isinstance(value, str):
            if escape:
                value = value.replace("'", "''")
            return f"'{value}'"
        elif isinstance(value, (int, float)):
            return str(value)
        elif isinstance(value, bool):
            return str(int(value)).upper()
        elif value is None:
            return 'NULL'
        elif isinstance(value, bytes):
            return f"b'{value.hex()}'"
        elif isinstance(value, list):
            return f"({', '.join(self.format_value(v, escape) for v in value)})"
        elif isinstance(value, tuple):
            return f"({', '.join(self.format_value(v, escape) for v in value)})"
        elif isinstance(value, dict):
            return f"{{{', '.join(f'{k}={self.format_value(v, escape)}' for k, v in value.items())}}}"
        else:
            raise TypeError(f"Unsupported type: {type(value)}")
