def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    formatted_sql = sql
    converted_params = []

    if self.SQLParams.in_style == NamedParameterStyle:
        for params in many_params:
            param_dict = {key: params[key] for key in params}
            formatted_sql, converted_params_list = self.formatone(formatted_sql, param_dict)
            converted_params.append(converted_params_list)
    elif self.SQLParams.in_style == OrdinalParameterStyle:
        for params in many_params:
            formatted_sql, converted_params_list = self.formatone(formatted_sql, params)
            converted_params.append(converted_params_list)

    return formatted_sql, converted_params

