    for logical_path, content_files in inventory.items():
        if not isinstance(logical_path, str) or not isinstance(content_files, list):
            raise ValueError("Invalid inventory format")

        # Step 3: Add the logical path and content files to the map
        if logical_path not in logical_path_map:
            logical_path_map[logical_path] = set()

        # Step 4: Add each content file to the set
        for file in content_files:
