def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""

    output = []
    spaces = ' ' * indent

    if debug:
        output.append(f"{spaces}<class {self.__class__.__name__}>")
        indent += 4

    for key, value in self.__dict__.items():
        if isinstance(value, dict):
            output.append(f"{spaces}{key} = {{")
            for k, v in value.items():
                output.append(f"{spaces}  {k}: {v}")
            output.append(f"{spaces}}}")
        elif isinstance(value, list):
            output.append(f"{spaces}{key} = [")
            for item in value:
                output.append(f"{spaces}  {item}")
            output.append(f"{spaces}]")
        else:
            output.append(f"{spaces}{key}: {value}")

    return '\n'.join(output)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    output = ""
    if debug:
        output += " " * indent + f"{self.__class__.__name__}(\n"
    for key, value in self.__dict__.items():
        if isinstance(value, list):
            output += " " * (indent + 2) + f"{key}=[\n"
            for item in value:
                if hasattr(item, 'pretty'):
                    output += item.pretty(indent + 4, debug)
                else:
                    output += " " * (indent + 4) + f"{item},\n"
            output += " " * (indent + 2) + "],\n"
        elif isinstance(value, dict):
            output += " " * (indent + 2) + f"{key}={value},\n"
        else:
            output += " " * (indent + 2) + f"{key}={value},\n"
    if debug:
        output += " " * indent + ")\n"
    return output.rstrip(",\n")

