def absorb(args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for expr in args:
        if isinstance(expr, tuple) and len(expr) == 3 and expr[1] in ('&', '|'):
            left, op, right = expr
            if op == '&':
                if isinstance(right, tuple) and len(right) == 3 and right[1] == '|':
                    if right[0] == left:
                        result.append(left)  # A & (A | B) = A
                    elif right[2] == left:
                        result.append(right[2])  # A & (B | A) = A
                elif isinstance(right, tuple) and len(right) == 3 and right[1] == '&':
                    if right[0] == left or right[2] == left:
                        result.append(left)  # A & (A & B) = A
            elif op == '|':
                if isinstance(right, tuple) and len(right) == 3 and right[1] == '&':
                    if right[0] == left:
                        result.append(left)  # A | (A & B) = A
                    elif right[2] == left:
                        result.append(right[2])  # A | (B & A) = A
                elif isinstance(right, tuple) and len(right) == 3 and right[1] == '|':
                    if right[0] == left or right[2] == left:
                        result.append(left)  # A | (A | B) = A
        else:
            result.append(expr)
    return result

