def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expression):
        if expression.type == 'binary':
            if expression.operator in ['&', '|']:
                left = apply_absorption(expression.left)
                right = apply_absorption(expression.right)
                if left.type == 'binary' and left.operator == expression.operator and left.left == expression.left:
                    return left
                if right.type == 'binary' and right.operator == expression.operator and right.right == expression.right:
                    return right
                if left.type == 'binary' and left.operator == expression.operator and left.right is expression.right:
                    return apply_absorption(BinaryExpression(left.left, expression.operator, right))
                if right.type == 'binary' and right.operator == expression.operator and right.left is expression.left:
                    return apply_absorption(BinaryExpression(right.right, expression.operator, left))
        return expression

    def apply_negative_absorption(expression):
        if expression.type == 'binary':
            if expression.operator == '&':
                left = apply_negative_absorption(expression.left)
                right = apply_negative_absorption(expression.right)
                if right.type == 'binary' and right.operator == '|' and right.left == expression.left and right.right == Expression('True'):
                    return expression.left
                if left.type == 'binary' and left.operator == '|' and left.right == expression.right and left.left == Expression('True'):
                    return expression.right
                if right.type == 'binary' and right.operator == '|' and right.left == Expression('True') and right.right is expression.right:
                    return apply_absorption(BinaryExpression(left.right, '&', expression.right))
                if left.type == 'binary' and left.operator == '|' and left.right == Expression('True') and left.left is expression.left:
                    return apply_absorption(BinaryExpression(right.right, '&', expression.left))
            elif expression.operator == '|':
                left = apply_negative_absorption(expression.left)
                right = apply_negative_absorption(expression.right)
                if right.type == 'binary' and right.operator == '&' and right.left == expression.left and right.right == Expression('True'):
                    return expression.left
                if left.type == 'binary' and left.operator == '&' and left.right == expression.right and left.left == Expression('True'):
                    return expression.right
                if right.type == 'binary' and right.operator == '&' and right.left == Expression('True') and right.right is expression.right:
                    return apply_absorption(BinaryExpression(left.right, '|', expression.right))
                if left.type == 'binary' and left.operator == '&' and left.right == Expression('True') and left.left is expression.left:
                    return apply_absorption(BinaryExpression(right.right, '|', expression.left))
        return expression

    new_args = []
    for arg in args:
        new_arg = apply_absorption(arg)
        new_arg = apply_negative_absorption(new_arg)
        new_args.append(new_arg)
    return new_args
