def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    def apply_absorption_and_negative_absorption(expr):
        if expr['type'] == 'binary':
            if expr['op'] == '&':
                if expr['left']['type'] == 'binary' and expr['left']['op'] == '|':
                    if expr['left']['left'] == expr['right']:
                        return expr['left']['left']
                elif expr['left']['type'] == 'binary' and expr['left']['op'] == '&':
                    if expr['left']['left'] == expr['right']:
                        return expr['left']['left']
            elif expr['op'] == '|':
                if expr['left']['type'] == 'binary' and expr['left']['op'] == '&':
                    if expr['left']['right'] == expr['right']:
                        return expr['left']['right']
                elif expr['left']['type'] == 'binary' and expr['left']['op'] == '|':
                    if expr['left']['right'] == expr['right']:
                        return expr['left']['right']
        return expr

    new_args = []
    for arg in args:
        new_args.append(apply_absorption_and_negative_absorption(arg))

    return new_args

