def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """

    num_objects = 0
    good_objects = 0

    for obj in self.iterate(include_self=True):
        num_objects += 1

        if validate_objects and not obj.validate():
            if show_warnings:
                print(f"Warning: Object {obj} is invalid.")
        else:
            good_objects += 1

        if check_digests and obj.has_digest():
            if obj.digest != obj.generate_digest():
                if show_warnings:
                    print(f"Warning: Object {obj} has an invalid digest.")
                else:
                    return num_objects, good_objects

    return num_objects, good_objects

