def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if isinstance(version, str):
        version = version.strip()

    if not version or not version[0].isdigit():
        raise ValueError("Invalid version format")

    version_parts = version.split('.')
    next_version_parts = []

    for part in reversed(version_parts):
        if part.isdigit():
            part = str(int(part) + 1)
            next_version_parts.append(part)
            while next_version_parts and next_version_parts[-1] == '0':
                next_version_parts.pop()
            break
        else:
            next_version_parts.append(part)

    if not next_version_parts:
        next_version_parts.append('1')

    next_version_parts.reverse()
    return '.'.join(next_version_parts)

