def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    for version_dir in version_dirs:
        inventory_file = os.path.join(version_dir, 'inventory.txt')
        if not os.path.exists(inventory_file):
            raise FileNotFoundError(f"Inventory file not found for version directory: {version_dir}")

        with open(inventory_file, 'r') as file:
            inventory_content = file.read()

        if version_dir == version_dirs[0]:
            root_inventory_content = inventory_content
        else:
            self._check_inventory_consistency(version_dir, inventory_content, root_inventory_content)

    self._record_content_digests(version_dirs)

def _check_inventory_consistency(self, version_dir, version_inventory_content, root_inventory_content):
    if version_inventory_content != root_inventory_content:
        raise ValueError(f"Inconsistent inventory for version {version_dir}. Expected: {root_inventory_content}, but found: {version_inventory_content}")

