def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    parts = url.split('?')
    base_url = parts[0]
    query_string = parts[1] if len(parts) > 1 else ''

    if query_string:
        query_items = query_string.split('&')
        new_query_items = []
        seen_keys = set()

        for item in query_items:
            key, value = item.split('=')
            if key in url_args:
                new_query_items.append(f"{key}={url_args[key]}")
                seen_keys.add(key)
            else:
                new_query_items.append(item)

        for key, value in url_args.items():
            if key not in seen_keys:
                new_query_items.append(f"{key}={value}")

        new_query_string = '&'.join(new_query_items)
        url = f"{base_url}?{new_query_string}"

    return url

