def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int) or not isinstance(alphabet, list) or not all(isinstance(c, str) for c in alphabet):
        raise ValueError("Invalid input: number must be an integer, and alphabet must be a list of strings.")

    if number < 0:
        raise ValueError("Negative numbers cannot be converted using this function.")

    if padding is not None and not isinstance(padding, int) or padding is not None and padding < 0:
        raise ValueError("Padding must be a non-negative integer.")

    if not alphabet:
