    The output has the most significant digit first.
    """
    if not isinstance(number, int) or not isinstance(alphabet, list) or not (padding is None or isinstance(padding, int)):
        raise ValueError("Invalid input types")

    if number < 0 or not alphabet:
        raise ValueError("Number must be non-negative and alphabet must not be empty")

    if padding is not None and padding < 0:
        raise ValueError("Padding must be non-negative")

    result = []
    while number > 0:
