import json
import hashlib
from datetime import datetime

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """

    if document_path is None:
        document_path = '/.well-known/nodeinfo'

    # Basic nodeinfo content template
    nodeinfo = {
        "version": "2.0",
        "software": {
            "name": "YourAppName",
            "version": "1.0"
        },
        "protocols": ["activitypub"],
        "services": {
            "inbounds": [],
            "outbounds": []
        },
        "usage": {
            "users": {
                "total": 1000
            }
        },
        "features": {
            "parsing": True,
            "import-export": True
        },
        "metadata": {}
    }

    # Hash the nodeinfo to ensure cryptographic integrity
    data = json.dumps(nodeinfo, sort_keys=True).encode('utf-8')
    nodeinfo["metadata"]["fingerprint"] = {'algorithm': 'sha256', 'digest': hashlib.sha256(data).hexdigest()}

    # Add the timestamp
    now = datetime.utcnow().isoformat() + 'Z'
    nodeinfo["metadata"]["crawled"] = now

    # Add the canonical link
    nodeinfo["links"] = [{
        "rel": "alternate",
        "type": "application/json"
    }]

    # Return the document
    return nodeinfo
