def parse_webfinger_xml(root):
    """
    Helper function to parse a Diaspora webfinger XML document.

    :param root: root element of the XML document
    :returns: dict with parsed data
    """
    data = {}
    for link in root.findall('{http://jabber.org/protocol/disco#info}link'):
        rel = link.get('rel')
        href = link.get('href')
        if rel == 'self' or rel == 'alternate':
            data['url'] = href
        elif rel == 'http://joindiaspora.org/ns/chat':
            data['chat'] = href
        elif rel == 'http://ostatus.org/schema/1.0/invite':
            data['invite'] = href
    return data

