        raise ValueError("spec_option must be a string")

    file_names = []
    for settings_dir in settings_dirs:
        try:
            if spec_option == 'files':
                file_names.extend([f for f in os.listdir(settings_dir) if os.path.isfile(os.path.join(settings_dir, f))])
            elif spec_option == 'directories':
                file_names.extend([f for f in os.listdir(settings_dir) if os.path.isdir(os.path.join(settings_dir, f))])
            else:
                raise ValueError("spec_option must be either 'files' or 'directories'")
        except FileNotFoundError:
            print(f"Directory {settings_dir} not found")
        except PermissionError:
            print(f"Permission denied for directory {settings_dir}")

    return file_names

