        list: A list of file names from the specified directories and specification option.
    """
    file_list = []

    if not isinstance(settings_dirs, list):
        settings_dirs = [settings_dirs]

    for directory in settings_dirs:
        if os.path.isdir(directory):
            for filename in os.listdir(directory):
                if os.path.isfile(os.path.join(directory, filename)) and filename.endswith(spec_option):
