def resolve_source(self, source_path):
    path_parts = source_path.split('.')
    current_obj = self
    for part in path_parts:
        try:
            current_obj = getattr(current_obj, part)
            if callable(current_obj):
                current_obj = current_obj()
        except (AttributeError, KeyError):
            return None
    return current_obj

