import os
import json

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    if not os.path.isDirectory(plugin_dir):
        raise ValueError("The provided path is not a valid directory")

    spec_file_path = os.path.join(plugin_dir, "plugin.spec.json")

    if not os.path.isfile(spec_file_path):
        raise FileNotFoundError("The plugin spec file does not exist")

    with open(spec_file_path, 'r') as spec_file:
        spec_data = json.load(spec_file)

    def flatten_dict(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    return flatten_dict(spec_data)
